CREATE TABLE jobs (_id INTEGER PRIMARY KEY AUTOINCREMENT, thread INTEGER NOT NULL, address TEXT NOT NULL, body TEXT NOT NULL, base INTEGER NOT NULL, sub INTEGER NOT NULL, due INTEGER NOT NULL, approved INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', uri TEXT NOT NULL DEFAULT '', parts INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, auto_send INTEGER NOT NULL DEFAULT 0, profile_revision INTEGER NOT NULL DEFAULT 0, config_revision TEXT NOT NULL DEFAULT '', original TEXT NOT NULL DEFAULT '');
CREATE TABLE receipts(job INTEGER, part INTEGER, result INTEGER, PRIMARY KEY(job,part));
CREATE TABLE drafts(thread INTEGER PRIMARY KEY, base INTEGER NOT NULL, body TEXT NOT NULL, alternatives TEXT NOT NULL, engine TEXT NOT NULL);
CREATE TABLE relationships(thread INTEGER PRIMARY KEY, body TEXT NOT NULL, revision INTEGER NOT NULL, samples TEXT NOT NULL DEFAULT '', cloud_enabled INTEGER NOT NULL DEFAULT 0, auto_draft INTEGER NOT NULL DEFAULT 0, relationship_kind TEXT NOT NULL DEFAULT '', tone TEXT NOT NULL DEFAULT '', auto_send INTEGER NOT NULL DEFAULT 0, auto_delay INTEGER NOT NULL DEFAULT 300);
